def sigmoid(z):
    """Sigmoid with clipping to avoid overflow"""
    z = np.clip(z, -30, 30)
    return 1 / (1 + np.exp(-z))

def brier_score(y_true, y_pred):
    """Brier score: mean squared error between predicted probabilities and binary labels"""
    return np.mean((y_pred - y_true) ** 2)

def create_folds(n_samples, n_splits=5):
    """Create contiguous fold indices.
    Fold k is the k-th consecutive slice of size n_samples // n_splits
    """
    fold_size = n_samples // n_splits
    folds = []
    for k in range(n_splits):
        start = k * fold_size
        end = start + fold_size
        folds.append((start, end))
    return folds

# Verify fold creation
folds = create_folds(140, 5)
print(f"Folds (start, end): {folds}")
for i, (start, end) in enumerate(folds):
    print(f"Fold {i}: rows {start}-{end-1} (size {end-start})")
